-- URMA · step 32 · The front of each competency form
--
-- Every competency form opens with the same boxes - Scope, Prerequisites, Recorded Recognition of
-- Current Competence, Assessment - and a version line. Only Scope was loaded before, and it was
-- loaded badly: the reader ran across both columns of the page, so a scope like "The L1 Alpine
-- Summer instructor can:" came out with the Assessment column spliced through the middle of it.
-- This reads all four boxes off the 2024 templates again, cropping to each printed box so the
-- columns cannot run into each other, and puts them on the competency.
--
-- Scope is REPLACED where the new reading found something, because what is there now is wrong.
-- The other three are only filled where they are empty, so corrections you make are kept.
--
-- Not every form has all four: most have no Recorded Recognition box at all, which is why only 24
-- of the 62 get one. Two forms (TL4-15 and CL3-04) are laid out differently enough that nothing
-- came across, and a few came across with a word clipped where a heading wrapped. It is ordinary
-- editable text. Treat it as a starting point and fix what is wrong.
--
-- Safe to run again.

begin;

alter table competencies add column if not exists scope            text;
alter table competencies add column if not exists prerequisites    text;
alter table competencies add column if not exists rrcc_text        text;
alter table competencies add column if not exists assessment_notes text;

update competencies c set
  version          = coalesce(c.version,          v.version),
  scope            = coalesce(v.scope,            c.scope),
  prerequisites    = coalesce(c.prerequisites,    v.prereq),
  rrcc_text        = coalesce(c.rrcc_text,        v.rrcc),
  assessment_notes = coalesce(c.assessment_notes, v.assess)
from (values
  ('CL1-03','2025, version 1','This competency is required for any instructor leading groups in the normal local operating area under supervision of the Duty Manager.','• 20 personal days in a variety of disciplines • 10 days experience as a leader in the outdoors','Prior Industry Experience and Tertiary Diploma level 5 or above + Induction into Hillary Outdoors Policy''s Any NZOIA Level 1 or above + Induction into Hillary Outdoors Policy''s','• Observations should be done during initial training period for all new staff • Discussion and observation by a Senior Instructor for at least one of the observations, Outdoor Instructor for the other. • Assessment to be at 2 sites or activities • Consider use of Questions 1-7 from the NZOIA Core Knowledge Workbook'),
  ('CL1-05','2025, version 1','This competency is compulsory for all persons who have sole charge of students.','None.','of Current Competence','• Observations should be done during initial training period for all new staff • Assessment through discussion and observation by an Outdoor Instructor or higher'),
  ('CL1-06','2025, version 1','This competency is required for any Instructor delivering at Hillary Outdoors.','None.','Diploma In Outdoor Education L5 or higher Teaching qual or 4 years industry experience + Hillary Outdoors Program Induction','• Observations should be done during initial training period for all new staff • Through discussion and observation • Assessor must be a Senior Instructor for at least one of the observations, can be done by an Outdoor Instructor for the other • Assessment to be with 2 different groups'),
  ('CL1-08','2025, version 1','The L1 bush instructor can: Lead and manage groups on formed and marked tracks, easy access to tracks or on strong linear features in the bush and open terrain This may include minor river crossings or short travel in stream-ways. The following are examples of environments that could be within the scope: ✓ Tracks on our local map that are well defined ie from kiwi lookout to base ✓ River travel up the Tangiaro stream ✓ L1 Bush Trips Tongariro','• No less than 10 days (4 hours duration) experience bush walking • 5 additional days as leader or co-leader in a bush environment. • Local famil of traplines',null,null),
  ('CL1-11','2025, version 1','The L1 instructor can: Lead and manage groups on in defined campsites in a bush/water environments within the local operating area with easy access The following are examples of environments within the scope: ✓ Little acre ✓ Piwakawaka pools ✓ The grove ✓ Other campsites on property ✓ Waikawau doc campsite ✓ Level 1 campsites Tongariro','• No less than 10 nights personal camping • 5 additional nights as leader or co-leader • L1 Bush or L1 Summer Alpine or L1 Water competencies',null,'Observations can be done by anyone with the Overnight (L1) Competency. Assessor must be an • Outdoor Instructor holding Overnight (L1) with Training department approval • or NZOIA Bush 1. Assessment is by observation and discussion'),
  ('CL1-14','2025, version 1','• There is well defined access for the participant to the abseil and the site allows for simple participant management. • The setup is on pre-arranged anchors • Personal safety can be set up simply • The base of the abseil is easy to manage Instructor must be signed as competent at each site before working solo with a group. Sites within the scope may include: ✓ Tangiaro Abseil Site( set up only not including bottom retrieval) ✓ L1 sites Tongariro with famil','• Complete at least 10 personal abseils at a variety of sites off their own set-ups • no less than 5 additional days as a leader or co-leader assisting with set-up and management',null,'Assessor must be an Outdoor Instructor step 2 and hold • Rock Climbing (L2) and Training Department approval • Or - NZOIA Rock 1, alpine 2 or cave 1. Assessment is by direct observation Assessment is site specific. Instructor must demonstrate competence at each site. Competency is achieved once signed off at a single site but: The instructor may only operate unsupervised at sites that have been assessed/approved. Famil''s may be done by NZOIA Rock 1 or equivalent Internal Competency'),
  ('CL1-17','2025, version 1','➢ The holder of this qualification can organise bouldering where the landing zone is flat and hazard free and the climbers'' feet do not exceed a height of 1.6 metres off the ground. ➢ Can set up and manage up to 3 single pitch top rope climbs where: • There is well defined access to the top rope anchors or haul lines. • There is a pre-arranged anchor set-up. • The instructor has visited the site previously and had their set up approved • Personal safety can be set up simply using an approved system. Instructor must be signed as competent at each site before working solo with a group. Sites within the scope may include:',null,null,'Observation/supervision can be done by an Outdoor Instructor with Rock Climbing (L1) Assessor must hold • Outdoor Instructor step 2, with Rock Climbing (L2) with Training department approval • NZOIA Rock 1 Instructor must demonstrate competence at each site Competency is achieved once signed off at two approved sites. The instructor may only operate unsupervised at sites that have been approved.'),
  ('CL1-20','2025, version 1','Can lead a kayaking activity on flat or sheltered water. This includes the ocean when the hazards present no greater risk than flat water. The following are examples of flat or sheltered water environments that are within this scope unless adverse weather conditions suggest otherwise • Port Charles • Big Sandy • Stoney bay • Waikawau estuary float • Flat water venues Tongariro This competency covers sit-on kayaks, sea kayak and Giant Sup Each craft needs its own assessment Instructor must be familiar with each site before working solo with a group.',null,null,'Observation/training can be done by an instructor with L1 Kayak competency. Assessor must hold • Outdoor Instructor with Flat water (L1) in relevant craft and Training department approval • Relevant NZOIA Level 1 or internal equivalent The instructor may operate at other sites with approval.'),
  ('CL1-23','2025, version 1','With this competency an instructor is able to instruct students using the low ropes and initiatives located around Hillary Outdoors property','• Five days experience instructing low ropes elements and initiatives',null,'• Observation can be done by a Developing Instructor with L1 Initiatives and Low Ropes. • Assessor must be an Outdoor Instructor with this ABL (L1). with Training department approval Assessment is by direct observation • Assessment must be at the local Low ropes plus 2 other activity sites Other'),
  ('CL1-25','2025, version 1','Instructor will be able to manage groups at simple prescribed coasteering venues. • Little bay to Waikawau • Otautu bay • Black Rock coaster','• 5 days coasteering experience • Risk management • Famil at sites before assessment with group',null,'Observation may be done by outdoor instructor stage 1 with competency Assessment must be done by outdoor instructor stage 1 with L2 coasteering'),
  ('CL1-28','2025, version 1','This competency is required for any staff driving vehicles of Hillary outdoors inclusive of vans, towing trailers and the tractor','• Full drivers licence sighted and scanned','Nil','• To be done through direct assessment by Senior Instructors.'),
  ('CL1-30','2024, version 1','The instructor with this competency is able to drive Kaitiaki, Hillary Outdoors inflatable support boat during daylight hours only, within the geographical limits in the Safe Operational Plan. Environmental conditions-less than 15Kn, less than 1.5m Swell','Safety Management, First Aid and Risk Management competencies 18 Years of age Knowledge of Tier 2 Instructor Handbook and AMPs for support boats Familiarity with the Safe operational Plan for Hillary outdoors Support boats.',null,null),
  ('CL1-33','2025, version 1','Instructor will be able to manage surf sports sessions in sit on top kayaks, Soft top surfboards (below 0.7m), body boards and body surfing''s in below 1.5m face height waves • Waikawau • Big sandy',null,null,'Observation may be done by outdoor instructor stage 1 with competency Assessment must be done by senior instructor with competency or training department approval'),
  ('CL1-36','2025, version 1','This is a requirement for any activities conducted in the surf eg Surf Kayaking, Surfing, boogie boarding, Swimming at beaches with surf over 0.5m maximum surf 1.5m Sites within the scope may include: Waikawau, Big sandy (in some conditions),',null,null,'Observation can be done by an instructor with this competency Assessment Must be done by senior instructor or Training department approval and involvement'),
  ('CL2-03','2025, version 1','The L2 Bush can: Lead and instruct groups in easy to moderate off track terrain. Trips can be above the bush-line in summer conditions where snow is not normally encountered. Can instruct groups in river crossing and stream/river travel. As Indirect the instructor can lead multi day trips when camping at formed or approved campsites. (Full sign off excluding camping skills) As Complete the Instructor can lead multi day camping trips to formed or unformed campsites. (Full sign off including camping skills) Terrain where a rope is not needed. Steep ground and Rope use only if with the L2 Management of steep ground - Bush & Alpine Summer The following are examples of environments that could be within the scope:  Potiki bay to Port Charles via paper road  Kauaeranga valley tramping  L2 bush venues Tongariro',null,null,'Training must be done before assessment, not together Observation can be done by an instructor with this L2 competency plus Training department approval. Assessor must be Senior Instructor or NZOIA Bush 1 training department approval'),
  ('CL2-06','2025, version 1','Ground where a rope or careful group management is required',null,null,'Training to be done by someone with minim this competency Assessment for Summer and Bush by a NZOIA Bush 2, NZOIA Alpine 1 or Senior Instructor with this Competency'),
  ('CL2-07','2025, version 1','Instructor will be able to manage groups at prescribed coasteering venues which may involve jumps which require management or using surge features to play • Rowner bay • Stoney bay',null,null,'Observation may be done by outdoor instructor stage 1 with competency Assessment must be done by senior instructor with this competency or training department approval'),
  ('CL2-10','2024, version 1','The instructor with this competency is able to drive Manaia, Hillary Outdoors inflatable support boat, within the geographic limits in the Safe Operational Plan. Normal operation is within daylight hours, however in the case of an emergency (e.g. medical evacuation) Manaia may be utilised at night. Environmental Conditions- less than 30Kn, Swell less t han 2m','Level 1 Support Boat Competency Safety Management, First Aid and Risk Management competencies 20 Years of age Knowledge of Tier 2 Instructor Handbook and AMPs for support boats Familiarity with the Safe operational Plan for Hillary outdoors Support boats. Documented evidence of at least 30 hrs boating experience in single outboard powered vessels of > 4m','RYA Powerboating Level','Assessor must be an approved assessor as per the Maritime NZ approved training plan.'),
  ('CL2-13','2026, version 1','Instructor will be able to manage sea kayaks in prescribed areas of water that may be affected by tide, swell, wind in places • Big Sandy to Stony bay • Waikawau to Potiki bay','• L1 Sea kayak • 10 days sea kayaking with groups',null,'Observation may be done by outdoor instructor stage 1 with competency Assessment must be done by senior instructor with competency or training department approval'),
  ('CL2-16','2025, version 1','Instructor will be able to manage waka taurua • Port Charles Level 1 area • Post Charles to Stoney Bay Level 2 on appropriate day (low swell, low wind)','• Boat theory competency lvl 1 • L1 sheltered water competency',null,'Observation may be done by outdoor instructor stage 1 with competency Assessment must be done by senior instructor with competency or training department approval'),
  ('CL2-19','2025; version 1','The instructor can organise and instruct bouldering, top- rope climbing and abseiling at single pitch rock sites using fixed and placed protection anchors. Instructor must have had a famil at each site before climbing with students. This instructor may be considered for work as an assistant instructor on an intro rock course. Sites within the scope may include:',null,null,'This is to be assessed in addition to the L1 rock and L1 abseil competencies. Training must be done before assessment, not together Observation can be done by an instructor with L2 Rock Climbing competency. Assessor must hold NZOIA Rock 1 or equivalent with training department approval, Assessment is by direct observation and questioning. Competency is achieved once signed off at a site within the L2 scope other than any used for L1 sign-off.'),
  ('CL3-02','2024, version 9','Instructor will be able to manage groups at prescribed coasteering venues which may involve jumps which require management or using surge features to play • Rowner bay • Stoney bay','• L1 Coasteering • 3 Trips at L1 Coasteering sites • Famil at sites before assessment with group',null,'Observation may be done by outdoor instructor stage 1 with competency Assessment must be done by senior instructor with this competency or training department approval'),
  ('CL3-04','2025, version 1',null,null,null,null),
  ('TL1-03','2024, version 9','This competency is required for any instructor leading groups in the normal local operating area under supervision of the Duty Manager.','• 20 personal days in a variety of disciplines • 10 days experience as a leader in the outdoors','2 Years Prior Industry Experience or Tertiary Diploma level 5 or above + Induction into the Hillary Outdoors Policy''s. Any NZOIA Level 1 or above + Induction into Hillary Outdoors Policy''s.','• Observations should be done during initial training period for all new staff • Discussion and observation by a Senior Instructor for at least one of the observations, Outdoor Instructor for the other. • Assessment to be at 2 sites or activities • Consider use of Questions 1-7 from the NZOIA Core Knowledge Workbook'),
  ('TL1-05','2024, version 9','This competency is compulsory for all persons who have sole charge of students.','None.','None.','• Observations should be done during initial training period for all new staff • Assessment through discussion and observation by an Outdoor Instructor or higher'),
  ('TL1-06','2024, version 9','This competency is required for any Instructor delivering at Hillary Outdoors.','None.','Diploma In Outdoor Education L5 or higher Teaching qual or 3 years experience in the Outdoor Education Industry + Hillary Outdoors Program Induction','• Observations should be done during initial training period for all new staff • Through discussion and observation • Assessor must be a Senior Instructor for at least one of the observations, can be done by an Outdoor Instructor for the other • Assessment to be with 2 different groups'),
  ('TL1-08','2024, version 9','The L1 Alpine Summer instructor can: Lead and manage groups on formed and marked tracks, easy access to tracks or on strong navigational features above the bush line in non- technical terrain in the Tongariro National Park where snow is not normally encountered. The following are examples of environments that are within the scope. Tongariro via west ridge; Wairere Valley; Pehi Crag circuit; (Not Pehi''s traverse) Tama Lakes circumnavigation; Whakapapa Village ridge track and Wairere Stream loop Pukekaikiore via Grand Gully; - Requires L2 Steep Ground Managment • All trips must be predominantly within range of the radio repeater','• No less than 10 days (4 hours duration) experience walking in the alpine environment above the bush-line • 5 additional days as leader or co-leader within the scopeL1 Field Communication L1 Risk Management L1',null,null),
  ('TL1-11','2024, version 9','With this competency an instructor is able to use an ice axe and take students into non-technical terrain where there may be enough snow cover for sliding. They are able to run a single day experience in snow to approved sites that have a low avalanche rating: o within the ski-field boundary. or o places with easy access to tracks or terrain without snow o easy access of the Mangatepopo valley floor. Ice axes may be issued to students, as a walking aid, and Primary Anchor NOT for self-arresting. The instructor may only operate at sites that have been approved on the day with consideration of the current environmental conditions The instructor must request DM approval if venturing on a new route. The following are examples of environments that may be within the scope under suitable environmental conditions They should always have DM approval: ✓ Head of Mangatepopo Valley and South Crater ✓ Scoria flat to Meads Wall via ridge and point 1716 (with specific approval regarding snow conditions) ✓ Hut Flat via Tenant''s Valley and the ridge above Aorangi ski lodge near Mead''s Wall ✓ The valleys SW of Iwikau below 1800m originating from the Amphitheatre ✓ Tama Lakes The level one instructor should carry a GPS/NZ TOPO 50 APP in poor weather.',null,null,'Observation may be done by an Outdoor Instructor with Alpine Winter (L1). Assessor: Must be a Outdoor Instructor step 2 with Alpine Winter (L2), or NZOIA Alpine 1 with Training department approval This L1 Competency is achieved once signed off at two sites within the scope The instructor must request DM approval if venturing on a new route even with full sign off..'),
  ('TL1-14','2024, version 9','The L1 bush instructor can: Lead and manage groups on formed and marked tracks, easy access to tracks or on strong linear features in the bush and open terrain. Walks may extend above the bush-line at low altitudes in good weather conditions and the absence of snow. This may include minor river crossings or short travel in stream-ways. Local bush bashing around HOEC centre with route plan approved. The following are examples of environments that could be within the scope: ✓ Most tracks on the Hillary Outdoors local map ✓ Off track on Local Map "Bush bashing" – Note the M.O.W Bush bash has steep terrain. ✓ Silica Rapids walk, ✓ Lower Tama Lake, ✓ Whakapapaiti track. ✓ Taurewa Stream (needs fimal and assessment) Note. Can be RCC signed off as Indirect with NZOIA Leader or Equivalent, With DM approval can access maintained tracks, Common HOEC Bush tracks and local Off track, Must Seek Approval Each time.','• No less than 10 days (4 hours duration) experience bush walking with 3 Days being off Track. • 5 additional days as leader or co-leader in a bush environment.','Competence • NZOIA Bush 1 • 15 Logged bush instruction days + Observation',null),
  ('TL1-17','2024, version 9','The L1 instructor can: Lead and manage groups on bush/water/alpine camps within the local operating area within easy access of well-defined tracks. Camping may extend above the bush line in good weather conditions and the absence of snow The following are examples of environments within the scope: ✓ Blue Gums, ✓ Club Med, ✓ Lake Otamangakau, ✓ Marty''s ✓ TNP huts ✓ Lower Tama Lake, Marty''s ✓ Wairere Stream above Taranaki Falls Note. Can be RCC signed off as Indirect with NZOIA Overnight Endorsement or Equivalent, With DM approval can access maintained campsites or easy access campsites on the local map must seek DM Approval each time.',null,null,'Observations can be done by anyone with the Overnight (L1) Competency. Assessor must be an • Outdoor Instructor holding Overnight (L1) with Training department approval • or NZOIA Bush 1. Assessment is by observation and discussion'),
  ('TL1-20','2024, Version 9','The L1 instructor can: Camp in tents at a designated camp site close to (guideline: <2 hours), and with non-technical access to, a major track or road. Designated campsites are as follows  Meads wall area above Aorangi hut: GR 208537  Lower Meads Wall area east of Happy Valley: GR 207537  West of Waikato hut (in view of the hut): GR 205535  The Wairere Valley less than 1.5 km from Taranaki Falls  Lower Tama Lake  Basin behind 1409, W Ridge, Tongariro','• L1 Alpine winter • 5 personal overnight days experience camping in the snow environment • Overnight (L1)',null,'Assessor must hold NZOIA Alpine 1 or A Senior Instructor with Alpine Winter Camp (L1) and Alpine Winter - (L2) with Training department approval Assessment is by direct observation'),
  ('TL1-22','2024, version 9','• There is well defined access for the participant to the abseil and the site allows for simple participant management. • The setup is on pre-arranged anchors • Personal safety can be set up simply • The base of the abseil is easy to manage Instructor must be signed as competent at each site before working solo with a group. Sites within the scope may include: ✓ The north end of Meads Wall with specific training for access ✓ MOW rock wall ✓ High Ropes course ✓ Pukehinau Abseil Taranaki falls is outside L1 scope but possible after additional training on rigging and operation.','• Complete at least 10 personal abseils at a variety of sites off their own set-ups • no less than 5 additional days as a leader or co-leader assisting with set-up and management',null,'Assessor must be an Outdoor Instructor step 2 and hold • Rock Climbing (L2) and Training Department approval • Or - NZOIA Rock 1, alpine 2 or cave 1. Assessment is by direct observation Assessment is site specific. Instructor must demonstrate competence at each site. Competency is achieved once signed off at a single site but: The instructor may only operate unsupervised at sites that have been assessed/approved. Famil''s may be done by NZOIA Rock 1 or equivalent Internal Competency'),
  ('TL1-25','2024, version 9','➢ The holder of this qualification can organise bouldering where the landing zone is flat and hazard free and the climbers'' feet do not exceed a height of 1.6 metres off the ground. ➢ Can set up and manage up to 3 single pitch top rope climbs where: • There is well defined access to the top rope anchors or haul lines. • There is a pre-arranged anchor set-up. • The instructor has visited the site previously and had their set up approved • Personal safety can be set up simply using an approved system. Instructor must be signed as competent at each site before working solo with a group. Sites within the scope may include:','• Climb no less than 20 top-rope climbs of any grade at a variety of sites (indoor or outdoor) • No less than 5 additional days as a leader or co-leader assisting with set-up and management',null,'Observation/supervision can be done by an Outdoor Instructor with Rock Climbing (L1) Assessor must hold • Outdoor Instructor step 2, with Rock Climbing (L2) with Training department approval • NZOIA Rock 1 Instructor must demonstrate competence at each site Competency is achieved once signed off at two approved sites. The instructor may only operate unsupervised at sites that have been approved.'),
  ('TL1-28','2024, version 9','Can lead a kayaking, Canoe and Sea kayak activity on flat or sheltered water. This includes rivers when the flow and the hazards present no greater risk than flat water. The following are examples of flat or sheltered water environments that are within this scope unless adverse weather conditions suggest otherwise • Lake Otamanaku • Te Whaiau Canal • Tokaanu tail race This competency covers sit-on kayaks, decked kayak, sea kayak and open canoe. Each craft needs its own assessment Instructor must be familiar with each site before working solo with a group.','• decked kayak: No less than 5 sessions (two hours +). And...* • sea kayak: No less than 5 sessions (two hours +) And...* • canoe: No less than 5 sessions (two hours +) And...* • * and... 3 days additional sessions as a leader or co-leader in any watercraft.',null,'Observation/training can be done by an instructor with L1 Flat water competency and relevant craft sign off. Assessor must hold • Outdoor Instructor with Flat water (L1) in relevant craft and Training department approval • Relevant NZOIA Level 1 or internal equivalent The instructor may operate at other sites with approval.'),
  ('TL1-31','2024, version 9','➢ This is a requirement for any water corridor trip involving crossings, tube floating and possibly swims and Tawhai falls. ➢ The holder of this qualification can be the assistant instructor on the following; grade 2 sit-on, Mavic, canoe or tube raft trip when combined with the relevant sign off e.g. Grade 2 assist. Sites within the scope may include: Mangatepopo tube float; Pukehinau Stream; upper Managatepopo Stream; Jo''s Cave to Conical Hill. Tawhai Falls can be signed off as indirect without completing the full sign off, but requires a famil from Senior instructor or training department approval.',null,'Competence • NZOIA Kayak 1 • NZOIA Canoe 1 • NZOIA Bush 2 • Approved 2-day river safety course • NZRA Grade','Observation can be done by an instructor with • Bush (L2) • River Safety (L1) Assessor must hold • NZOIA kayak 1, NZOIA Canoe 1, NZOIA Bush 2 • Senior Instructor with internal equivalent with Training department approval If a Diploma lvl 5 with river rescue modules is held, Consider RCC for Personal skill''s, can be done through discussion.'),
  ('TL1-33','2024, version 9','The holder of this qualification can be the assistant instructor on a grade 2 Mavric, sit-on or tube raft trip. Kayaks within the scope include: Closed kayaks endorsement with a roll. Sites within the scope include: Tongariro from Red Hut','• L1 River Safety','Competence • NZOIA Kayak 1 • Hillary Outdoors Diploma L5 + River Safety (L1) • Independent Grade 2 Paddler with a reliable roll.','Observation Can be done by an instructor with Grade 2 trip leader. Assessment Assessor must be Outdoor Instructor step 2 and hold Grade 2 trip leader with Training department approval NZOIA kayak'),
  ('TL1-35','2024, Version 9','With this competency, the instructor is able to lead trips in simple horizontal caves with site specific sign-off. Sites within the scope may include: ✓ Pukehinau Cave ✓ Okupata Cave ✓ Walk down Dry Valley and up the Pukehinau Stream','• L1 Communication • Complete site induction of a round trip of Okupata Cave: main entrance, knee deep pool, escape route to upper entrance.','Competence • NZOIA Cave 1 • 5 personal and 5 Logged Instruction days + Observation and local famil','Observation Can be done by a Developing Instructor step 2. Assessment Assessor must be an Outdoor Instructor step 2 and hold Cave (L1) with Training department approval Assessment is by direct observation and site specific The instructor may only operate unsupervised at sites that have been approved.'),
  ('TL1-37','2024, version 9','This competency is for those operating all basic elements of the Hillary Outdoors High Ropes. NB: There is a specific L2 Competency for the Trapeze and the Big Swing and above ground rescues. The instructor must be on direct supervision for these elements until assessed as competent','• Knowledge and relevant experience of current standard practice in New Zealand ropes skills.','Competence All Require site famil • High Ropes Certificate • NZOIA Rock Leader + famil 2 ropes only • NZOIA rock 1 • 10 Logged Instruction days in HR + observe and famils • Some RCC From Rock Climbing (L1)','Observation can be done by an Outdoor Instructor. Assessor must be a Senior Instructor with Training department approval Assessment is by direct observation'),
  ('TL1-39','2024, Version 9','With this competency an instructor is able to operate the flying fox and perform a rescue of a stranded person.','• Three sessions under supervision',null,'• Observation can be done by a Developing Instructor with L1 flying Fox. • Assessor must be a Outdoor Instructor with L1 Flying Fox with Training department approval • Assessment is by direct observation'),
  ('TL1-40','2024, Version 9','With this competency an instructor is able to instruct students using the low ropes and initiatives located around Hillary Outdoors property','• Five days experience instructing low ropes elements and initiatives',null,'• Observation can be done by a Developing Instructor with L1 Initiatives and Low Ropes. • Assessor must be an Outdoor Instructor with this ABL (L1). with Training department approval Assessment is by direct observation • Assessment must be at the local Low ropes plus 2 other activity sites Other'),
  ('TL2-03','2024, Version 9','Preform above ground work including pull cord retrievals and rescues. Set up and Manage the Big Swing and Trapeze',' High Ropes level',null,'• Training can be completed by a instructor with this Competency • Assessment to be completed by a Senior Instructor with this Competency or Outdoor Instructor step 2 with this Competency and Training Team approval'),
  ('TL2-05','2024, Version 9','Ground where a rope or careful group management is required',' For steep ground Summer - Bush (L1), Alpine Summer (L1)  For Steep Ground Winter – Bush (L1), Alpine Summer (L1), Winter Alpine (L1)','• NZOIA Bush 2 (Bush and Summer Alpine Only) • NZOIA Alpine 1 or equivalent','Training to be done by someone with minim this competency Assessment for Summer and Bush by a NZOIA Bush 2, NZOIA Alpine 1 or Senior Instructor with this Competency Assessment for Snow – NZOIA Alpine 1 or L3 Alpine Competency'),
  ('TL2-07','2024, Version 9','The L2 Alpine Summer instructor can: Lead and manage groups on day scrambles and multi- day trips in the local mountain environment off track where snow is not normally encountered. The operational area may include areas that cannot be serviced through the Taurewa repeater. Trips may be through remote and untracked terrain such as:  Circumnavigation of Ngauruhoe via Tongariro summit, headwaters of Waihohonu Stream, upper Tama Lake and Middle Earth crag  Tongariro via South Ridge  Te Heuheu and descend via Waihohonu Ridge to Wairere Stream',' L1 alpine Summer  L2 Management of steep ground - Bush & Alpine Summer  L1 Camping  No less than 10 days (4 hours duration) experience walking in the alpine environment above the bush-line predominantly away from tracks  3 days as leader or co-leader instructing within the scope of this competency. (must be recorded in a training log)','• NZOIA Bush 2 • NZOIA Alpine 1 • NZOIA Bush 1 + L2 Management of steep ground - Bush & Alpine Summer','Training must be done before assessment, not together Observation can be done by an instructor with this Summer Alpine (L2) competency. Assessment Assessor must be Sinor Instructor with this competency and training department approval. or hold NZOIA Bush 2 or NZOIA Alpine 1 with Training Department approval. Assessment is by direct observation and conversation'),
  ('TL2-10','2024, Version 9','For those instructing and managing groups on day excursions in the winter alpine environment. The range is to be less than 4 hours from a vehicle or hut. It is for travelling on non-technical ground (Logan grade 1) where ice axes are standard equipment to carry. A rope is not normally required but may be used on occasions to safeguard students on steep or exposed ground. Crampons may be introduced on easy terrain. An Instructor must work within the scope of their current avalanche training as per the Tier 2 hand book. The following are examples of environments that could be within the scope:  Restful Ridge to Dome Shelter, back via the Notch  Tongariro West Ridge to Saddle and down via Red Crater  Broken Leg Gulley, upper Pinnacle Ridge to Te Heuheu',' L1 Alpine Winter  Management of steep ground - Bush & Alpine (winter)  20 days experience in the winter alpine environment  10 days as co-instruct or instruct in the winter alpine environment',null,'Training must be done before assessment, not together Observation can be done by an instructor with alpine winter L2 competency. Assessment Assessor must hold NZOIA Alpine 1 or equivalent with Training Department Approval or Alpine Instruction L4 Comp. Assessment is by direct observation and professional conversation'),
  ('TL2-13','2024, version 9','Tents With this competency an instructor can camp in tents within the L2 Winter Alpine scope Snow shelters endorsement Construct and use a variety of snow shelters in areas within the L2 Alpine Winter scope.',null,null,'Observation can be done by an instructor with this competency. Assessor – Winter Camp Tents. Senior Instructor with this competency and training department approval or NZOIA Alpine 1 Snow Shelter Endorsement Observation can be done by an instructor with the full competency. Assessor Senior Instructor with this competency and training department approval or NZOIA Alpine 2 Assessment is by direct observation'),
  ('TL2-16','2024, version 9','The L2 Bush can: Lead and instruct groups in easy to moderate off track terrain. Trips can be above the bush-line in summer conditions where snow is not normally encountered. Can instruct groups in river crossing and stream/river travel. As Indirect the instructor can lead multi day trips when camping at formed or approved campsites. (Full sign off excluding camping skills) As Complete the Instructor can lead multi day camping trips to formed or unformed campsites. (Full sign off including camping skills) Terrain where a rope is not needed. Steep ground and Rope use only if with the L2 Management of steep ground - Bush & Alpine Summer The following are examples of environments that could be within the scope:  Umukarikari Range in the southern Kaimanawa  Around the mountain track  Extended off-track trips in the local HOEC environments',null,null,'Training must be done before assessment, not together Observation can be done by an instructor with this L2 competency plus Training department approval. Assessor must be Senior Instructor or NZOIA Bush 1 training department approval'),
  ('TL2-20','2024; version 9','The instructor can organise and instruct bouldering, top-rope climbing and abseiling at single pitch rock sites using fixed and placed protection anchors. Instructor must have had a famil at each site before climbing with students. This instructor may be considered for work as an assistant instructor on an intro rock course. Mangatepopo Falls Abseil has a separate L3 Competency Sites within the scope may include:',' L1 Rock Climbing  L1 Abseil  At least 25 days rock climbing experience at a variety of venues including 15 days personal climbing, 10 days climbing instruction and 5 abseil sessions.',null,'This is to be assessed in addition to the L1 rock and L1 abseil competencies. Training must be done before assessment, not together Observation can be done by an instructor with L2 Rock Climbing competency. Assessor must hold NZOIA Rock 1 or equivalent with training department approval, Assessment is by direct observation and questioning. Competency is achieved once signed off at a site within the L2 scope other than any used for L1 sign-off.'),
  ('TL2-23','2024, version 9','Unsheltered or remote areas of flatwater <2 hours from vehicle or <0.5hrs from landing Moving water up to Grade 1 This Instructor can: Take groups on unsheltered water such as Kuratau river mouth and bay trip, Motuapa Peninsular. Kawakawa Bay','L1 Flat water + 10 days in an appropriate craft in these conditions.',null,'Training to be delivered by an Outdoors Instructor who holds this competency. Assessment to be done by a Senior Instructor with this competency or NZIOA Sea Kayak 1 or NZOIA Canoe 1 or Equivalent with training department approval.'),
  ('TL2-25','2024, version 9','To be trip leader and instruct and manage inflatable kayak and sit-on kayak trips from a closed kayak on grade 2. Sites within the scope may include:  Lower Tongariro from Blue Pool  Lower Tongariro From Red Hut','L1 Kayak Grade 2 with closed kayak endorsement 5 flat water teaching sessions 10 personal trips on grade 2 5 days personal kayaking on grade 3 No less than 5 days as a leader or assistant leader in a closed cockpit kayak on grade','Competence: • NZOIA Kayak 1 with local famil','Observation can be done by an instructor with L2 Kayak Grade 2 Trip Leader Assessor must be a Senior Instructor holding NZOIA Kayak 1 or Internal equivalent'),
  ('TL2-28','2024, Version 9','The instructor with L2 Upper Mangatepopo assist competency can: Assist managing groups in the Upper Mangatepopo River, including upstream to the high point access and down through all the jumps above the Mangatepopo Falls abseil. Must Have level 1 River Safety Note: The Mangatepopo Falls Abseil is a separate L3 Competency','L1 River Safety 2 trips without students or as an observer',null,'Observation can be done by an instructor with L2 competency Upper Mangatepopo River Trip Assessor must be a Senior Instructor with the Upper Mangatepopo Trip Leader. Assessment is by direct supervision'),
  ('TL2-31','March 2024, version 9','The instructor can manage a group on the Meads Wall Traverse. It does not cover the competency to rig the traverse','L2 Rock 2 trips as a co-instructor','Competence: • NZOIA Rock 2 or Cave','• Training must be done before assessment, not together • Observation can be done by a Senior instructor with the L2 Traverse comp • Assessor must hold NZOIA Rock 2 or equivalent, or Approval from the Training Department. Assessment is by direct observation and questioning.'),
  ('TL3-03','2024, Version 9','The instructor with L3 Upper Mangatepopo Trip Lead competency can: Lead and manage groups in the Upper Mangatepopo River, including upstream to the high point access and down through all the jumps above the Mangatepopo Falls abseil. Trip Leader must be fully signed off for the competency Note: The Mangatepopo Falls Abseil is listed under L3 Mangatepopo Falls Abseil competency','L1 River Safety Trip Assistant 4 trips with students as an assistant','Competence: • NZOIA Canyon 1 with at least one trip as an observer or assistant','Observation can be done by an instructor with L3 competency including L3 Upper Mangatepopo Trip Lead. Assessor must hold L3 competency Upper Mangatepopo Trip Lead, assessment is by direct supervision and to be approved by the Training Department'),
  ('TL3-06','2024, version 9','Abseiling Mangatepopo Falls','L2 Rock Climbing or NZIOA Rock 1 L1 River Safety',null,'Assessor must hold NZIOA Canyon 1 or NZIOA Rock 1 plus this competency and have Training Department Approval. Assessment is by direct observation and questioning.'),
  ('TL3-07','2024, version 9','The holder of this qualification can organise and instruct overnight Sea Kayaking trips on open water areas where adverse conditions and limited periods of exposed coast may be encountered. Adverse conditions being; wind up to 15 knots and swell of up to 1 metre. The competency also allows the instructor to lead an expedition on grade 1. An example of a trip would be to Te Hapua Bay to camp or a Delta trip on the Tongariro River.','L1 Sea Kayak L1 Camp No less than 15 days sea kayaking, to include: No less than 10 days co-instructing or instructing','Competence: • NZOIA Sea Kayak 1 with local famil • Or NZOIA Seak Kayak','Training must be done before assessment, not together Observation can be done by an instructor with L2 sea kayak Assessor must hold NZOIA Sea Kayak 2 or NZOIA Sea Kayak 1 with local knowledge and training department approval or hold this internal sign off with training department approval. Assessment is by direct observation'),
  ('TL3-11','2024, Version 9','With this competency an instructor can organise and lead and teach progressions to effectively lead a trip on class 1+ water. The instructor should be able to assist on a Whanganui River expedition with the class 2 endorsement Sites within the scope may include:  Motuoapa to Stump Bay circuit  Lower Delta to Tokaanu  Te Hapua Bay  Just outside L2 scope: Tongariro from Major Jones to SH1','L1 Canoe L1 River Safety L1 Camping 5 trips on moving water to include 3 sessions of at least 2 hours duration instructing to the scope of this award including teaching moving water progressions 2 overnight camping trips with canoes','Competence: • Logged White Water and Canoe Experience • NZOIA Canoe','Training can be done by an instructor with L2 Canoe and TM approval. Assessor must hold Level 3 including NZOIA Canoe1 or equivalent. Assessment is by direct observation'),
  ('TL3-14','2024, Version 9','Rig and Derig the Meads Wall Traverse','• Rock 1 or Equivalent • 100 Days of Experience placing Trad or • L2 Rock','• NZIOA Cave','Training and Assessment to be done by an instructor with this competency and Training Department approval'),
  ('TL3-15','2024, Version 9','For those teaching progressions for closed cockpit kayaks on moving water up to grade 2 This is comparable to NZOIA Kayak 1 Sites within the scope may include: • Mohaka: McVicker''s – Fisherman''s • Tongariro from Blue Pool • Aniwhenua of the Rangitaiki','L2 Kayak grade 2 Trip Leader 10 flat water teaching sessions 10 moving water instruction sessions 15 rolling teaching sessions',null,'Observation and supervision can be done by an instructor with L3 kayak or NZOIA Kayak 1. Assessor must hold the equivalent of NZOIA Kayak'),
  ('TL3-18','2024, Version 9','This competency is for those instructors who may instruct on tertiary rock programmes (under supervision of an instructor with NZOIA Rock 2 or equivalent) and have the ability to teach technical rock climbing, including all aspects of a NZOIA rock one syllabus and extending through to teaching single pitch lead climbing on bolts (NZOIA Lead climb endorsement) and traditional placed protection.','• All L1 comps, • NZOIA level one rock or Rock climbing L2. • An additional 10 days climbing at a variety of climbing crags including leading 10 climbs at grade 18 or above. • Lead at least 5 climbs, grade 18 or above, using placed (trad) gear',null,'Training must be done before assessment, not together Observation can be done by an instructor with L3 rock instructor plus TM approval. Assessor must hold NZOIA Rock two or equivalent. Assessment is by direct observation and logbook evidence'),
  ('TL4-07','May 2020, version 3','The holder of this qualification can organise, instruct and lead multi-day canoe trips on moving water up to class 2. Adverse conditions being wind up to 10 knots and swell no higher than the freeboard. Sites within the scope may include:  Whanganui River from Taumaranui to Pipiriki  Whanganui River from Kakahi to Piriaka  Tongariro River from Red Hut','L2 Canoe 10 days experience on at least 2 different class 2 rivers 10 days of instructing or guiding experience (including 5 days on grade 2) The total must include 3 multi-day trips (one being of two or more nights)','Competence: NZOIA Canoe','Training can be done by an instructor with L3 Canoe or equivalent and TM approval. Assessor must hold Level 3 including NZOIA Canoe1 or equivalent.'),
  ('TL4-11','May 2020, version 2','This competency is for those instructors who may instruct on tertiary rock programmes (under supervision of an instructor with NZOIA Rock 2 or equivalent) and have the ability to teach technical rock climbing, including all aspects of a NZOIA rock one syllabus and extending through to teaching single pitch lead climbing on bolts (NZOIA Lead climb endorsement) and traditional placed protection.','All L1 comps, NZOIA level one rock or Rock climbing L2. An additional 10 days climbing at a variety of climbing crags including leading 10 climbs at grade 18 or above. Lead at least 5 climbs, grade 18 or above, using placed (trad) gear','Competence: NZOIA Rock 2  RCC for Rock 1 if held','Training must be done before assessment, not together Observation can be done by an instructor with L3 rock instructor plus TM approval. Assessor must hold NZOIA Rock two or equivalent. Assessment is by direct observation and logbook evidence'),
  ('TL4-15','February 2016, version 1',null,null,null,null),
  ('TL4-19','September 2017, version 2','Instruct Multi-day alpine climbing trips up to grade 2 Sites within the scope may include:  Pinnacles East Ridge  Paritetaitonga  Girdlestone West Ridge','No less than 25 days personal climbing and at least one 3000m peak and two alpine Grade 3 climbs Have logged some South Island experience in glaciated terrain. No less than 25 days instructing/leading groups in alpine climbing at least five or these days will include co-instructing or working as an assistant instructor/trainee beyond the scope of Alpine 1 NZOIA Alpine 1 or L3 Alpine Avalanche Risk Management Stage 1 (NZQA L5)','Competence: NZOIA Alpine 2 MIC','Training must be done before assessment, not together Observation can be done by an instructor with L4 alpine competency. Assessor must hold NZOIA Alpine 2. Assessment is by direct observation')
) as v(code, version, scope, prereq, rrcc, assess)
where c.code = v.code;

commit;

-- Expect: scope 60, prerequisites 47, rrcc 24, assessment 56, of 62.
select count(*) filter (where scope is not null)            as with_scope,
       count(*) filter (where prerequisites is not null)    as with_prerequisites,
       count(*) filter (where rrcc_text is not null)        as with_rrcc,
       count(*) filter (where assessment_notes is not null) as with_assessment,
       count(*)                                             as competencies
  from competencies;

-- Any scope that still has another column spliced through it would show up here:
select code, name, level from competencies
 where scope ilike 'Scope %' or scope ilike '%Prerequisites%' order by code;
